public static BigInteger toUnsignedBigInteger(final long val) {
  return new BigInteger(1, new byte[]{
      (byte) (val >>> 56), (byte) (val >>> 48), (byte) (val >>> 40), (byte) (val >>> 32),
      (byte) (val >>> 24), (byte) (val >>> 16), (byte) (val >>> 8), (byte) val
  });
}
